set-variable.value:
#[{
                    'UNKNOWN'       : { code: 500, reason: 'Internal Server Error', message: 'default' },
                    'HTTP:NOT_FOUND': { code: 404, reason: 'Not Found', message: 'exact' },
                    'HTTP:*'        : { code: 599, reason: 'Any HTTP', message: 'anyIdentifier' },
                    '*:TIMEOUT'     : { code: 408, reason: 'Timeout', message: 'anyNamespace' }
                }]

#[%dw 2.0 import * from module_error_handler_plugin::common --- getPreviousErrorMessage({
                    childErrors: [
                        { errorMessage: { payload: 'Route 0 failed' } },
                        { errorMessage: { payload: 'Route 1 failed' } },
                        { errorMessage: { payload: 'Route 0 failed' } }
                    ]
                })]

#[%dw 2.0 import * from module_error_handler_plugin::common --- getPreviousErrorMessage({
                    childErrors: [],
                    suppressedErrors: [
                        { errorMessage: { payload: { error: { message: 'attempt 1 failed' } } } },
                        { errorMessage: { payload: { error: { message: 'attempt 2 failed' } } } }
                    ]
                })]

munit-tools:assert-equals.actual:
#[%dw 2.0 import * from module_error_handler_plugin::common --- getPreviousErrorMessage({
                    childErrors: [ { errorMessage: { payload: 'only failure' } } ]
                })]

#[%dw 2.0 import * from module_error_handler_plugin::common --- getPreviousErrorMessage({
                    errorMessage: { payload: 'plain text error body' }
                })]

#[%dw 2.0 import * from module_error_handler_plugin::common --- getPreviousErrorMessage({
                    errorMessage: { payload: ('binary error body' as Binary) }
                })]
